"""Migrated order_fulfilment workflow."""

from decimal import Decimal, InvalidOperation


def _positive_total(value: object) -> bool:
    """Implement NVL(TOT_AMT, 0) > 0 for legacy-style values."""
    if value is None or value == "":
        return False
    try:
        return Decimal(str(value)) > Decimal("0")
    except (InvalidOperation, ValueError, TypeError):
        return False


def _account_credit_hold(record: dict, tables: dict) -> object:
    """Return CRED_HOLD from the first live matching account row."""
    account_id = record.get("ACCT_ID")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG") != "Y" and row.get("ACCT_ID") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order-fulfilment transition."""
    new_record = dict(record)
    audits = []
    notifies = []
    new_state = state
    matched = False

    if state == "E" and event == "approve":
        if _positive_total(record.get("TOT_AMT")):
            new_state = "A"
            audits.append("ORD_APPR")
            matched = True

    elif state == "A" and event == "ship":
        new_state = "S"
        audits.append("ORD_SHIP")
        notifies.append("shipped")
        matched = True

    elif state == "S" and event == "invoice":
        new_state = "I"
        audits.append("ORD_INV")
        matched = True

    elif state == "E" and event == "cancel":
        new_state = "X"
        audits.append("ORD_CANC")
        matched = True

    elif state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            new_state = "X"
            audits.append("ORD_CANC")
            matched = True

    elif state == "I" and event == "cancel":
        new_state = "X"
        audits.append("ORD_CANC_INV")
        notifies.append("credit_note")
        matched = True

    if not matched:
        audits = ["WF_NOMATCH"]

    return {
        "state": new_state,
        "record": new_record,
        "audits": audits,
        "notifies": notifies,
        "matched": matched,
    }
